CREATE FUNCTION otelHistogramQuantile AS (q, bounds, counts) -> multiIf((arraySum(counts) = 0) OR (otelHQIdx(q, counts) = 0), NULL, otelHQIdx(q, counts) > length(bounds), bounds[length(bounds)], if(otelHQIdx(q, counts) = 1, 0., bounds[otelHQIdx(q, counts) - 1]) + ((((bounds[otelHQIdx(q, counts)]) - if(otelHQIdx(q, counts) = 1, 0., bounds[otelHQIdx(q, counts) - 1])) * ((q * arraySum(counts)) - if(otelHQIdx(q, counts) = 1, 0., arrayCumSum(counts)[otelHQIdx(q, counts) - 1]))) / (counts[otelHQIdx(q, counts)])));
